-- ============================================================
-- TNBIKE SALES DATABASE — Seed Data Import
-- Schema: tnbike · PostgreSQL 14+
-- ============================================================
-- Data: 2025-01-01 to 2026-02-28
-- Row counts: product_group=5, product_line=77, product=247,
--   product_price=1016, province=75, customer=702,
--   sales_order=1627, order_line=17031, fact_sales=17031
-- ============================================================

SET search_path TO tnbike, public;
SET client_encoding TO 'UTF8';
BEGIN;

-- ============================================================
-- 1. product_group (5 rows)
-- ============================================================
ON CONFLICT DO NOTHING;

-- ============================================================
-- 2. product_line (77 rows)
-- ============================================================
ON CONFLICT DO NOTHING;

-- ============================================================
-- 3. product (247 rows)
-- ============================================================
ON CONFLICT DO NOTHING;

-- ============================================================
-- 4. product_price (1016 rows)
-- ============================================================
ON CONFLICT DO NOTHING;

-- ============================================================
-- 5. province (75 rows)
-- ============================================================
ON CONFLICT DO NOTHING;

-- ============================================================
-- 6. customer (702 rows)
-- ============================================================
ON CONFLICT DO NOTHING;

-- ============================================================
-- 7. sales_order (1627 rows)
-- ============================================================
ON CONFLICT (so_number) DO NOTHING;

-- ============================================================
-- 8. order_line (17031 rows)
-- ============================================================
TRUNCATE tnbike.order_line CASCADE;

-- ============================================================
-- 9. fact_sales (generated from dimension tables)
-- ============================================================
TRUNCATE tnbike.fact_sales CASCADE;
    order_date, fiscal_year, fiscal_quarter, fiscal_month, week_of_year,
    so_number, order_id, line_id,
    customer_code, customer_name, province_id, province_name, region,
    product_code, product_name, color, line_id_fk, line_name, group_code, group_name,
    quantity, unit_price, line_total
)
SELECT
    so.order_date,
    so.fiscal_year,
    so.fiscal_quarter,
    so.fiscal_month,
    EXTRACT(WEEK FROM so.order_date)::SMALLINT  AS week_of_year,
    so.so_number,
    so.order_id,
    ol.line_id,
    so.customer_code,
    c.customer_name,
    c.province_id,
    p.province_name,
    p.region,
    ol.product_code,
    pr.product_name,
    pr.color,
    pl.line_id    AS line_id_fk,
    pl.line_name,
    pg.group_code,
    pg.group_name,
    ol.quantity,
    ol.unit_price,
    ol.line_total
FROM tnbike.order_line ol
JOIN tnbike.sales_order so   ON so.order_id    = ol.order_id
JOIN tnbike.customer c       ON c.customer_code = so.customer_code
JOIN tnbike.product pr       ON pr.product_code = ol.product_code
LEFT JOIN tnbike.product_line pl ON pl.line_id    = pr.line_id
LEFT JOIN tnbike.product_group pg ON pg.group_code = pl.group_code
LEFT JOIN tnbike.province p      ON p.province_id = c.province_id;

-- ============================================================
-- Row count verification
-- ============================================================
SELECT 'product_group'  AS tbl, COUNT(*) AS cnt FROM tnbike.product_group
UNION ALL SELECT 'product_line',  COUNT(*) FROM tnbike.product_line
UNION ALL SELECT 'product',       COUNT(*) FROM tnbike.product
UNION ALL SELECT 'product_price', COUNT(*) FROM tnbike.product_price
UNION ALL SELECT 'province',     COUNT(*) FROM tnbike.province
UNION ALL SELECT 'customer',      COUNT(*) FROM tnbike.customer
UNION ALL SELECT 'sales_order',   COUNT(*) FROM tnbike.sales_order
UNION ALL SELECT 'order_line',    COUNT(*) FROM tnbike.order_line
UNION ALL SELECT 'fact_sales',    COUNT(*) FROM tnbike.fact_sales;

COMMIT;